import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse('{"title":"Creating a plugin","description":"The `pnpm gen` generator, what it creates, and what to do next","frontmatter":{"navigation":{"category":"Getting started"},"title":"Creating a plugin","description":"The `pnpm gen` generator, what it creates, and what to do next","editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/docs/creating-a-plugin.md"},"headers":[],"relativePath":"guides/creating-a-plugin.md","filePath":"docs/creating-a-plugin.md","lastUpdated":1792347072000}'),a={name:`guides/creating-a-plugin.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="creating-a-plugin" tabindex="-1">Creating a plugin <a class="header-anchor" href="#creating-a-plugin" aria-label="Permalink to “Creating a plugin”">​</a></h1><p>Use <code>pnpm gen</code> to add a plugin package to this repository. The generator creates a working starter, registers it for releases, installs its workspace dependencies, and updates the generated README content. It leaves the changes in your working tree for you to review and develop; it doesn&#39;t commit them.</p><p>If you&#39;re building a plugin in its own repository, skip to <a href="#standalone-projects">Standalone projects</a>.</p><h2 id="create-the-package" tabindex="-1">Create the package <a class="header-anchor" href="#create-the-package" aria-label="Permalink to “Create the package”">​</a></h2><p>Run the generator from the repository root:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gen</span></span></code></pre></div><p>This runs the <code>plugin</code> <a href="https://turborepo.dev/docs/guides/generating-code" target="_blank" rel="noreferrer">Turborepo generator</a> defined in <code>turbo/generators/</code>. It asks for a folder name, the name Pumpkin displays, and a short description. These answers shape the package, its release tag, and its generated metadata, so choose them before you start adding behavior:</p><table tabindex="0"><thead><tr><th>Prompt</th><th>Example</th><th>What to enter</th></tr></thead><tbody><tr><td>Folder name</td><td><code>my-plugin</code></td><td>A new kebab-case name for <code>packages/</code>. It becomes the npm package suffix, release tag prefix, and <code>.wasm</code> file name. The folder must not already exist.</td></tr><tr><td>Plugin name</td><td><code>MyPlugin</code></td><td>A PascalCase name that Pumpkin displays and uses for <code>plugins/data/MyPlugin/</code>. It defaults to the folder name converted to PascalCase.</td></tr><tr><td>Description</td><td><code>Does a thing</code></td><td>A non-empty, single-line description of at most 70 characters. It appears in package metadata, the plugin README, and the root README package list; add a fuller explanation to <code>src/info.ts</code> later.</td></tr></tbody></table><p>To provide the same answers without prompts, pass them in that order:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --args</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MyPlugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Does a thing&quot;</span></span></code></pre></div><h2 id="what-the-generator-sets-up" tabindex="-1">What the generator sets up <a class="header-anchor" href="#what-the-generator-sets-up" aria-label="Permalink to “What the generator sets up”">​</a></h2><p>The new <code>packages/&lt;folder&gt;/</code> directory contains the files you need to begin:</p><ul><li><code>package.json</code>, <code>tsconfig.json</code>, and <code>vitest.config.ts</code> configure the package, build, and tests.</li><li><code>src/name.ts</code>, <code>src/info.ts</code>, <code>src/commands/spec.ts</code>, and <code>src/plugin.ts</code> define the plugin name, metadata, starter command, and behavior. The plugin name and command permission each have one source declaration.</li><li><code>test/plugin.itest.ts</code> loads the built plugin on a real Pumpkin server and checks that its starter <code>/plugin</code> command works. The integration-test task builds the package first.</li><li><code>README.md</code> starts with the plugin title and generated-content markers, including the component reference marker.</li></ul><p>The generator also registers the package in both Release Please files. It starts the package at <code>0.0.0</code> and pins its first release to <code>0.0.1</code>, regardless of the first commit type. The package metadata includes the repository&#39;s standard license and repository fields. <code>pnpm check</code> validates the description, those fields, and both release registrations. See <a href="/pumpkin-plugins/guides/ci-and-releases#registering-a-plugin-for-releases">Registering a plugin for releases</a> for how the first-release pin works.</p><p>After writing the files, the generator runs <code>pnpm install</code>, fills the plugin README from <code>src/info.ts</code>, adds its docs-site API reference link, updates the root README package list, and formats the new files with Biome. The <code>🧬 Generator</code> CI job also creates a throwaway plugin and typechecks, builds, and integration-tests it when the scaffold, generator setup, or generated plugin dependencies change. That check catches templates that have drifted out of working shape.</p><h2 id="make-it-your-plugin" tabindex="-1">Make it your plugin <a class="header-anchor" href="#make-it-your-plugin" aria-label="Permalink to “Make it your plugin”">​</a></h2><h3 id="choose-edition-support" tabindex="-1">Choose edition support <a class="header-anchor" href="#choose-edition-support" aria-label="Permalink to “Choose edition support”">​</a></h3><p>Plan for useful behavior on both Java and Bedrock. Features can differ, but a plugin that loads while leaving an edition&#39;s relevant experience unchanged doesn&#39;t count as supported on that edition.</p><p>Use the pinned Pumpkin API to identify host limits, and verify client-dependent behavior with the relevant real client before claiming it works. If the plugin&#39;s purpose requires a mod for one edition, or a required Pumpkin API or client capability is unavailable, document the unsupported edition and the reason in the plugin README. Keep behavior without real-client evidence marked as unverified.</p><p>Start with the metadata and starter command:</p><ol><li><p>Describe the plugin in <code>src/info.ts</code>, including any permissions, commands, or config. Replace or extend the starter command in <code>src/commands/spec.ts</code> with <code>defineCommands</code>. Keep its permission under the <code>COMMAND_PERMISSION</code> constant. <a href="/pumpkin-plugins/guides/plugin-info-and-readmes">Plugin info and READMEs</a> explains how these declarations feed Pumpkin metadata and the generated README.</p></li><li><p>Add plugin behavior in <code>src/plugin.ts</code>, inside the <code>onPluginLoad</code> hook. The starter extends <code>PluginBase</code> and calls <code>registerPlugin</code>; together they provide shared metadata, lifecycle logging, and the automatic update check. Read <a href="/pumpkin-plugins/guides/building">Building</a> before choosing APIs: Static Hermes is the default runtime and has runtime-specific API limits. Follow <a href="/pumpkin-plugins/guides/code-style">Code style</a>; public code needs JSDoc descriptions, and <code>pnpm lint</code> checks them.</p></li><li><p>If the plugin needs settings, declare them with <code>@pumpkin-plugins/config</code> and add that package as a dev dependency. See <a href="/pumpkin-plugins/guides/plugin-config">Plugin config</a>.</p></li><li><p>Build and test the package:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @pumpkin-plugins/my-plugin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> turbo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:integration</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter=@pumpkin-plugins/my-plugin</span></span></code></pre></div><p>Replace <code>my-plugin</code> with the package&#39;s folder name. The integration test loads the built plugin on a real Pumpkin server.</p></li></ol><h3 id="files-and-network-access" tabindex="-1">Files and network access <a class="header-anchor" href="#files-and-network-access" aria-label="Permalink to “Files and network access”">​</a></h3><p>The starter already enables the <code>http</code> capability for its automatic update check. To use file or socket APIs, include their WASI capabilities in <code>pumpkinPlugin.wasi</code> in <code>package.json</code>. For example:</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pumpkinPlugin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;entry&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;src/plugin.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;output&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;build/my-plugin.wasm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;wasi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;filesystem&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sockets&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;udp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span></code></pre></div><p>Declaring a capability makes its interface available to the plugin, but Pumpkin must also grant the matching permissions. Shared plugin metadata adds <code>http.outbound</code> for the automatic updater; list other permissions in <code>info.permissions</code>:</p><table tabindex="0"><thead><tr><th>Capability</th><th>Permissions you may need</th></tr></thead><tbody><tr><td><code>filesystem</code></td><td><code>fs.read.data</code> to read, <code>fs.write.data</code> to write. Both are limited to the plugin&#39;s own data folder, preopened as <code>data</code>.</td></tr><tr><td><code>sockets</code></td><td><code>network.tcp.bind</code> to listen, <code>network.tcp.connect</code> to connect out.</td></tr><tr><td><code>udp</code></td><td><code>network.udp.bind</code> to receive, <code>network.udp.outgoingdatagram</code> to send to any address, <code>network.udp.connect</code> to talk to one address.</td></tr><tr><td><code>http</code></td><td><code>http.outbound</code> for HTTP or HTTPS requests. The automatic updater already adds this permission.</td></tr></tbody></table><h2 id="without-the-generator" tabindex="-1">Without the generator <a class="header-anchor" href="#without-the-generator" aria-label="Permalink to “Without the generator”">​</a></h2><p>For a plugin in this monorepo, the generator handles several pieces that are easy to miss. If you create the package by hand, you can copy <code>packages/bedrock-addon-manager</code> or create a generated plugin and remove what you don&#39;t need. Then check that you:</p><ul><li>Register it in both <code>release-please-config.json</code> and <code>.release-please-manifest.json</code>, and start its <code>package.json</code> version at <code>0.0.0</code>. The first-release config entry needs <code>&quot;release-as&quot;: &quot;0.0.1&quot;</code>. See <a href="/pumpkin-plugins/guides/ci-and-releases#registering-a-plugin-for-releases">Registering a plugin for releases</a>; <code>node scripts/check-release-config.mjs</code> reports missing registration.</li><li>Run <code>pnpm install</code> so pnpm links the package into the workspace.</li><li>Run <code>pnpm readme</code> so the root package table and generated docs-site reference links include it.</li></ul><h2 id="standalone-projects" tabindex="-1">Standalone projects <a class="header-anchor" href="#standalone-projects" aria-label="Permalink to “Standalone projects”">​</a></h2><p>For a plugin in a separate repository, use <a href="./../tools/create-pumpkin-plugin/README"><code>create-pumpkin-plugin</code></a>. It offers TypeScript and JavaScript starters with the API and build dependencies, but it doesn&#39;t include <code>plugin-kit</code>, Release Please registration, or this repository&#39;s integration-test scaffolding.</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pumpkin-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-plugin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pumpkin-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-plugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pumpkin-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-plugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --js</span></span></code></pre></div><p>The interactive command asks which language to use. Add <code>--skip-install</code> to create the files without installing dependencies. The creator refuses an existing destination. Its README also documents npm, Yarn Classic, Yarn Modern, and Bun launch forms; the validated packed-consumer build contract covers pnpm only. See the <a href="/pumpkin-plugins/docs/plugin-api/">Plugin API guide</a> for API setup, lifecycle, ABI, and migration details.</p>`,33)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};